/**
 * Every route the API answers, with the permission that decides it.
 *
 * Plain data, grouped by catalogue area, one line per route. Each entry says
 * what decides access in the new engine:
 *   - a catalogue key ('sales.view'): the person needs that permission in the
 *     route's company (scoped keys also filter which records they see);
 *   - 'per_record': a check on the record itself decides (task and project
 *     visibility, conversation threads, approval-chain steps); `note` says how;
 *   - 'self': any signed-in person, acting on their own things;
 *   - 'portal': a client or influencer portal session, on its own records;
 *   - 'public': no session (share links, sign-in, webhooks, public game pages);
 *   - 'super_admin': the platform administrator only.
 *
 * `legacyRoles` is today's answer: the company roles the legacy gate lets in.
 * For routes in docs/superpowers/plans/gate-matrix.csv it is the matrix's roles
 * column; for the routers the matrix does not cover it was read from the
 * handler's gate (named in `note`). It is absent where no role list gates the
 * route. test/authz-route-registry.test.js proves that every route of the built
 * app is declared here exactly once, and that each system template grants each
 * role-gated route to exactly the roles in `legacyRoles`.
 *
 * Draft generated once from the gate matrix with an explicit old-to-new table;
 * maintained by hand from here on. A new route needs a line here or the test fails.
 */
import type { UserRole } from '../types';

export const DECLARATION_KINDS = ['public', 'self', 'super_admin', 'portal', 'per_record'] as const;
export type DeclarationKind = (typeof DECLARATION_KINDS)[number];

export interface RouteDecl {
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  path: string;
  /** A catalogue permission key, or how the route is decided instead. */
  permission: string;
  /** Today's allow-list of company roles; absent when the route is not role-gated. */
  legacyRoles?: readonly UserRole[];
  /**
   * `legacyRoles` deliberately differs from the gate matrix's roles column (or
   * the matrix has no gate): the handler checks more than the extracted gate.
   * `note` says what. The test allows a difference only with this marker.
   */
  legacyOverride?: true;
  note?: string;
}

